           backgroundcolor: rgba(255, 255, 255, 0.1);
       }
       .timeslot.selected {
           backgroundcolor: 0A84FF;
           bordercolor: 0A84FF;
           color: white;
       }
        .timeslot.disabled {
           backgroundcolor: rgba(50, 50, 50, 0.5);
           bordercolor: transparent;
           color: rgba(235, 235, 245, 0.4);
           cursor: notallowed;
