<body class="bgblack textneutral100">

   <! Háttérvideó >
   <video autoplay muted loop playsinline id="bgvideo">
       <source src="" type="video/mp4">
       A böngésződ nem támogatja a videó lejátszást.
   </video>

   <! Cím az oldal tetején >
   <header class="absolute top0 left0 right0 textcenter py10 sm:py12 z10">
       <h1 class="text5xl sm:text7xl fontbold trackingtight textwhite">Zsebibaba</h1>
   </header>

   <! Kártya konténer  középre igazítva >
   <div class="minhscreen flex flexcol itemscenter justifycenter p4 spacey8">

       <! Külön Időpontfoglalás gomb >
       <button id="opencalendarbtn" class="buttonprimary textlg">
          Időpontfoglalás (25 000 Ft)
       </button>

       <! Glassmorphism termékkártya >
       <div class="glasscard w72 h72 p4 flex flexcol itemscenter justifycenter textcenter">
           <div class="productinfo">
               <h2 class="text2xl fontsemibold mb3">Kis csomag</h2>
               <p class="textlg fontmedium textneutral300 mb5">10 000 Ft</p>
               <! Vásárlás gomb a termékhez >
               <button id="purchaseproductbtn" class="buttonsecondary textbase">
                  Vásárlás
               </button>
           </div>
       </div>
   </div>

   <! Időpontfoglaló Modális Ablak >
   <div id="bookingmodal" class="fixed inset0 bgblack bgopacity50 flex itemscenter justifycenter p4 z50 opacity0 invisible">
       <div class="glasscard wfull maxwlg p6 sm:p8 rounded3xl">
           <div class="flex justifybetween itemscenter mb6">
               <h3 class="text2xl fontbold">Időpontfoglalás</h3>
               <button id="closemodalbtn" class="textgray400 hover:textwhite text3xl leadingnone">×</button>
           </div>

           <! Naptár >
           <div>
               <div class="flex justifybetween itemscenter mb4">
                   <button id="prevmonthbtn" class="p2 roundedfull hover:bgwhite/10 transitioncolors">
                       <svg class="w6 h6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns=""><path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="M15 19l77 77"></path></svg>
                   </button>
                   <h4 id="currentmonthyear" class="textlg fontsemibold"></h4>
                   <button id="nextmonthbtn" class="p2 roundedfull hover:bgwhite/10 transitioncolors">
                       <svg class="w6 h6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns=""><path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="M9 5l7 77 7"></path></svg>
                   </button>
               </div>
               <div class="calendargrid mb4">
                   <div class="weekday">H</div><div class="weekday">K</div><div class="weekday">Sze</div><div class="weekday">Cs</div><div class="weekday">P</div><div class="weekday">Szo</div><div class="weekday">V</div>
               </div>
                <div id="calendardays" class="calendargrid"></div>
           </div>

           <! Idősávok >
           <div id="timeslotscontainer" class="mt6 hidden">
               <h4 class="fontsemibold mb3 textlg">Válassz időpontot:</h4>
               <div id="timeslots" class="grid gridcols3 sm:gridcols4 gap3">
                   <! Idősávok dinamikusan lesznek beillesztve >
               </div>
           </div>

           <button id="confirmbookingbtn" class="wfull mt8 buttonprimary textlg transitionopacity opacity50 cursornotallowed" disabled>
               Tovább az utaláshoz (25 000 Ft)
           </button>
       </div>
   </div>

   <script>
       document.addEventListener('DOMContentLoaded', function() {
           // Elemek
           const modal = document.getElementById('bookingmodal');
           const openCalendarBtn = document.getElementById('opencalendarbtn');
           const purchaseProductBtn = document.getElementById('purchaseproductbtn');
           const closeBtn = document.getElementById('closemodalbtn');
           const prevMonthBtn = document.getElementById('prevmonthbtn');
           const nextMonthBtn = document.getElementById('nextmonthbtn');
           const monthYearEl = document.getElementById('currentmonthyear');
           const calendarDaysEl = document.getElementById('calendardays');
           const timeSlotsContainer = document.getElementById('timeslotscontainer');
           const timeSlotsEl = document.getElementById('timeslots');
           const confirmBtn = document.getElementById('confirmbookingbtn');

           let currentDate = new Date();
           let selectedDate = null;
           let selectedTime = null;

           const availableTimeSlots = ["10:00", "11:00", "14:00", "15:00", "16:00", "18:00"];
           const bookedSlots = {}; // "YYYYMMDD": ["HH:MM"]

           //  KIS CSOMAG VÁSÁRLÁS (10 000 Ft) 
           purchaseProductBtn.addEventListener('click', () => {
               const accountNumber = '107000314973750901007378';
               const recipientName = 'Zsebeházi Andrea';
               const amount = '10000';
               const currency = 'HUF';
               const comment = 'Zsebibaba Kis Csomag';
               const paymentLink = iban:HU?acc=${accountNumber}&name=${encodeURIComponent(recipientName)}&amount=${amount}&curr=${currency}&msg=${encodeURIComponent(comment)};
               window.location.href = paymentLink;
           });


           //  Naptár logika 
           function renderCalendar() {
               const now = new Date();
               now.setHours(0, 0, 0, 0);
               const year = currentDate.getFullYear();
               const month = currentDate.getMonth();
               monthYearEl.textContent = ${year}. ${new Intl.DateTimeFormat('hu-HU', { month: 'long' }).format(currentDate)};
               calendarDaysEl.innerHTML = '';
               const firstDayOfMonth = new Date(year, month, 1).getDay();
               const daysInMonth = new Date(year, month + 1, 0).getDate();
               let firstDayIndex = (firstDayOfMonth === 0) ? 6 : firstDayOfMonth  1;
               for (let i = 0; i < firstDayIndex; i++) {
                   const emptyEl = document.createElement('div');
                   emptyEl.className = 'calendarday empty';
                   calendarDaysEl.appendChild(emptyEl);
               }
               for (let day = 1; day <= daysInMonth; day++) {
                   const dayEl = document.createElement('div');
                   const dayDate = new Date(year, month, day);
                   dayEl.className = 'calendarday';
                   dayEl.textContent = day;
                   if (dayDate < now) {
                       dayEl.classList.add('disabled');
                   } else {
                       dayEl.addEventListener('click', () => {
                           if(selectedDate && selectedDate.toDateString() === dayDate.toDateString()) {
                               selectedDate = null;
                               selectedTime = null;
                               timeSlotsContainer.classList.add('hidden');
                           } else {
                               selectedDate = dayDate;
                               selectedTime = null;
                               renderTimeSlots();
                           }
                           updateSelection();
                       });
                   }
                   if (selectedDate && dayDate.toDateString() === selectedDate.toDateString()) {
                       dayEl.classList.add('selected');
                   }
                   calendarDaysEl.appendChild(dayEl);
               }
               updateSelection();
           }

           function renderTimeSlots() {
               timeSlotsEl.innerHTML = '';
               if (!selectedDate) {
                   timeSlotsContainer.classList.add('hidden');
                   return;
               }
               timeSlotsContainer.classList.remove('hidden');
               const dateString = ${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')};
               const todaysBookedSlots = bookedSlots[dateString] || [];
               availableTimeSlots.forEach(time => {
                   const slotEl = document.createElement('div');
                   slotEl.className = 'timeslot border textcenter p2 roundedlg';
                   slotEl.textContent = time;
                   if (todaysBookedSlots.includes(time)) {
                       slotEl.classList.add('disabled');
                   } else {
                       slotEl.addEventListener('click', () => {
                           selectedTime = time;
                           updateSelection();
                       });
                   }
                   if (selectedTime === time) {
                       slotEl.classList.add('selected');
                   }
                   timeSlotsEl.appendChild(slotEl);
               });
           }

           function updateSelection() {
               document.querySelectorAll('.calendarday').forEach(el => {
                   el.classList.remove('selected');
                   const day = parseInt(el.textContent);
                   if (selectedDate && day === selectedDate.getDate() && currentDate.getMonth() === selectedDate.getMonth() && currentDate.getFullYear() === selectedDate.getFullYear()) {
                       el.classList.add('selected');
                   }
               });
               document.querySelectorAll('.timeslot').forEach(el => {
                   el.classList.remove('selected');
                   if (selectedTime && el.textContent === selectedTime) {
                       el.classList.add('selected');
                   }
               });
               if (selectedDate && selectedTime) {
                   confirmBtn.disabled = false;
                   confirmBtn.classList.remove('opacity50', 'cursornotallowed');
               } else {
                   confirmBtn.disabled = true;
                   confirmBtn.classList.add('opacity50', 'cursornotallowed');
               }
           }

           //  Modális ablak vezérlése 
           function openModal() { modal.classList.remove('opacity0', 'invisible'); }
           function closeModal() { modal.classList.add('opacity0', 'invisible'); }

           openCalendarBtn.addEventListener('click', openModal);
           closeBtn.addEventListener('click', closeModal);
           modal.addEventListener('click', (e) => { if(e.target === modal) closeModal(); });

           prevMonthBtn.addEventListener('click', () => {
               currentDate.setMonth(currentDate.getMonth()  1);
               renderCalendar();
           });
           nextMonthBtn.addEventListener('click', () => {
               currentDate.setMonth(currentDate.getMonth() + 1);
               renderCalendar();
           });

           //  IDŐPONT FOGLALÁS UTALÁS (25 000 Ft) 
           confirmBtn.addEventListener('click', () => {
               if (!selectedDate || !selectedTime) return;
               const formattedDate = ${selectedDate.getFullYear()}.${String(selectedDate.getMonth() + 1).padStart(2, '0')}.${String(selectedDate.getDate()).padStart(2, '0')};
               const accountNumber = '107000314973750901007378';
               const recipientName = 'Zsebeházi Andrea';
               const amount = '25000';
               const currency = 'HUF';
               const comment = Zsebibaba Idopontfoglalas - ${formattedDate} ${selectedTime};
               const paymentLink = iban:HU?acc=${accountNumber}&name=${encodeURIComponent(recipientName)}&amount=${amount}&curr=${currency}&msg=${encodeURIComponent(comment)};
               window.location.href = paymentLink;
               closeModal();
           });

           // Kezdeti renderelés
           renderCalendar();
       });
   </script>

</body>
</html>

